contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sender approves this contract (InvMutTest) to spend `amount` on its behalf,
    // then InvMutTest calls transferFrom(sender, recipient, amount) on c.
    // We check that if transferFrom does not revert then:
    //  - recipient balance increases by exactly amount
    //  - allowance from sender to address(this) decreases by exactly amount
    // Note: msg.sender for calls to c will be this contract (InvMutTest).
    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0), true);

        // read pre-state
        uint256 beforeRecipient = c.balanceOf(recipient);
        uint256 beforeAllowance = c.allowance(sender, address(this));

        // Attempt transferFrom and capture whether it reverts
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state (only public getters allowed)
        uint256 afterRecipient = c.balanceOf(recipient);
        uint256 afterAllowance = c.allowance(sender, address(this));

        // If transferFrom succeeded (did not revert) then:
        // 1) recipient balance increased by amount (no fees in transferFrom path for allowed roles here)
        // 2) allowance decreased by amount (or becomes 0 if underflow prevented by revert earlier)
        // We assert the conjunction: if not reverted then both conditions must hold.
        assert(reverted || (afterRecipient == beforeRecipient + amount && afterAllowance + amount == beforeAllowance));
    }

    receive() external payable {}
}

