contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that a successful transfer moves tokens from sender to recipient preserving total supply locally
    function run(address sender, address recipient, uint256 amount) public payable {
        // avoid zero-address reverts present in C
        require(sender != address(0) && recipient != address(0));

        // Read balances before using only public getters
        uint256 beforeSender = c.balanceOf(sender);
        uint256 beforeRecipient = c.balanceOf(recipient);

        // attempt transfer as if invoked by `sender`: since the test contract is the caller for calls on c,
        // we must simulate sender initiating the transfer by having c.transfer called with msg.sender == sender.
        // However, per constraints, the checker deploys c and then calls run with msg.sender being this contract
        // (InvMutTest). We therefore invoke c.transfer from this contract, which will use msg.sender == address(this).
        // To actually test general transfer behavior for arbitrary sender, we rely on transferFrom path instead:
        // Approve this contract for `amount` from `sender` then call transferFrom(sender, recipient, amount).
        // But approval must be done by `sender`, which we cannot make. Therefore, restrict to cases where
        // msg.sender (this contract) is the sender: call transfer to move tokens from this contract to recipient.
        // So require that `sender` equals address(this) to ensure the call exercises transfer path legitimately.
        require(sender == address(this));

        // When this contract is the sender, read its own balance as beforeSender (already read).

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterSender = c.balanceOf(sender);
        uint256 afterRecipient = c.balanceOf(recipient);

        // If the transfer did not revert, recipient's balance increases by amount and sender's balance decreases by amount.
        // To avoid underflow in the assert evaluation, express decreases as afterSender + amount == beforeSender
        // and increases as afterRecipient == beforeRecipient + amount.
        assert(reverted || (afterRecipient == beforeRecipient + amount && afterSender + amount == beforeSender));
    }

    receive() external payable {}
}

