contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to transfer tokens from this contract to `to`.
    // We take parameters: to (recipient) and amount (tAmount) and a boolean indicating
    // whether the test should attempt a transfer using transfer() (true) or transferFrom() (false).
    function run(address to, uint256 amount, bool useTransferFrom) public payable {
        require(to != address(0));

        // Observe total supply and this contract's balance before any state-changing calls
        uint256 totalBefore = c.totalSupply();
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        bool reverted = false;

        // If using transferFrom, first approve this contract (msg.sender for c calls is this test contract)
        if (!useTransferFrom) {
            // call transfer on c from this contract to `to`
            try c.transfer(to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // For transferFrom, we must approve msg.sender (which is this contract) as spender; but the contract
            // calling c.transferFrom will be this contract, and sender must be an address that holds tokens.
            // The InvMutTest contract is the sender in this scenario; transferFrom called by this contract
            // would require allowance from the sender (which is also this contract) to this contract: trivial.
            // However ERC20 logic normally expects allowance[sender][spender] where sender==this contract and spender==this contract.
            // To exercise transferFrom path, first approve this contract as spender for amount.
            try c.approve(address(this), amount) {
                // now call transferFrom(sender=this contract, recipient=to, amount)
                try c.transferFrom(address(this), to, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } catch {
                // approve reverted
                reverted = true;
            }
        }

        // Read after-state
        uint256 totalAfter = c.totalSupply();
        uint256 balThisAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // General rule: totalSupply is unchanged, and if the call did not revert then recipient's balance increased by amount
        // (i.e., balToAfter == balToBefore + amount). If the call reverted, balances must be unchanged.
        // Note: avoid underflow by using >= comparisons.
        assert(
            totalAfter == totalBefore
            && (
                reverted
                ? (balThisAfter == balThisBefore && balToAfter == balToBefore)
                : (balToAfter >= balToBefore && balToAfter - balToBefore == amount)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt a token move of `amount` from this contract to `to` using either transfer or transferFrom.
    // The function is single-entry and uses only top-level calls on c.
    function run(address to, uint256 amount, bool useTransferFrom) public payable {
        require(to != address(0));

        // Observe before-values (view calls allowed anywhere)
        uint256 totalBefore = c.totalSupply();
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        bool reverted;

        if (!useTransferFrom) {
            // top-level try/catch around the state-changing call
            try c.transfer(to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // approve then transferFrom are two separate top-level state-changing calls;
            // first attempt to approve this contract as spender for `amount` from this contract
            bool approveReverted;
            try c.approve(address(this), amount) {
                approveReverted = false;
            } catch {
                approveReverted = true;
            }

            if (approveReverted) {
                // If approve reverted, we won't attempt transferFrom; mark as reverted overall
                reverted = true;
            } else {
                // Now attempt transferFrom(sender = this contract, recipient = to, amount)
                try c.transferFrom(address(this), to, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        // Observe after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balThisAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // Single assert: totalSupply unchanged; if call succeeded, recipient gained exactly amount and this lost exactly amount;
        // if call reverted, balances unchanged.
        assert(
            totalAfter == totalBefore
            && (
                reverted
                ? (balThisAfter == balThisBefore && balToAfter == balToBefore)
                : (balToAfter == balToBefore + amount && balThisBefore == balThisAfter + amount)
            )
        );
    }

    receive() external payable {}
}

