contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take params to exercise both buy/sell branches and varying amounts.
    // senderIsAllowed determines whether msg.sender (this contract) will be given the allowed role
    // recipientIsAllowed determines whether the target address will be given the allowed role
    // tAmount is the transfer amount to attempt
    // target is the transfer counterparty
    function run(bool senderIsAllowed, bool recipientIsAllowed, address target, uint256 tAmount) public payable {
        require(target != address(0));

        // Initially record values observable from c
        uint256 beforeMin = c.minTxnAmount();
        uint256 beforePercent = c.percent();
        uint256 beforeRewardRate = c.rewardRate();

        // Ensure percent is nonzero to avoid division by zero — percent is public and set in constructor of C, but be safe
        // If percent == 0 this test is not meaningful; require it to be nonzero so division is well-defined
        require(beforePercent != 0);

        // We will operate using this contract's address as one party and `target` as the other.
        // The contract C exposes a mapping _allowedRoles privately; we can only flip allowed roles by calling changeOwner etc, but changeOwner is onlyOwner. However, InvMutTest is not owner. So we cannot directly set allowed roles. To still exercise both branches, rely on the fact that freshly deployed C sets owner to deployer (checker deploys C and passes here). We cannot change allowed roles, so restrict the rule to cases where either senderIsAllowed or recipientIsAllowed is false: these will exercise the normal transfer branch when neither is allowed, or one of the allowed branches if the deployer equals this contract (which generally it won't). To keep the property general and provable we only assert implications that refer to observable behavior.

        // Record txReward and contract token balance before action for potential beneficiary addresses
        uint256 beforeReward_target = c.txReward(target);
        uint256 beforeReward_me = c.txReward(address(this));

        uint256 before_bal_contract = c.balanceOf(address(c));

        // Decide which transfer to perform: from this contract to target, or from target to this contract.
        // We cannot invoke c.transferFrom from target because we are this contract; but we can call c.transfer to move tokens from this contract (msg.sender==InvMutTest)
        // So we will perform a transfer from this contract to `target` with amount tAmount.

        // To be allowed to transfer tokens, this contract must hold tokens. The freshly deployed C mints all tokens to its deployer, not to InvMutTest.
        // Thus many transfers will revert. We capture that via try/catch.
        bool didRevert = false;
        try c.transfer(target, tAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // After the attempted transfer, read observable values again
        uint256 afterReward_target = c.txReward(target);
        uint256 afterReward_me = c.txReward(address(this));
        uint256 after_bal_contract = c.balanceOf(address(c));

        // Compute expected rewardAmount using public params: when transfer is a buy (sender allowed) the recipient gets reward; when sell (recipient allowed) sender gets reward.
        // Because we cannot reliably set allowed roles, we assert a general implication: if the transfer succeeded (didRevert==false), tAmount >= minTxnAmount, and the contract had at least rewardAmount before, then exactly one of the txReward entries (for recipient or sender) increases by rewardAmount and the contract's balance decreases by rewardAmount. Otherwise txReward does not increase and contract balance is unchanged relative to reward issuance.

        uint256 rewardAmount = 0;
        if (beforeRewardRate != 0) {
            // compute tAmount * rewardRate / percent. Avoid overflow by using uint256 cast (both are uint256 already).
            rewardAmount = (tAmount * beforeRewardRate) / beforePercent;
        }

        // Define predicates observed
        bool txSucceeded = !didRevert;
        bool meetsMin = (tAmount >= beforeMin);
        bool contractHadReward = (before_bal_contract >= rewardAmount);

        // Now assert the general rule described above.
        // If transfer succeeded and meetsMin and contractHadReward and rewardAmount>0,
        // then either target's txReward increased by rewardAmount (buy-case) or this contract's txReward increased by rewardAmount (sell-case), and contract token balance decreased by rewardAmount.
        // Otherwise, neither txReward changed and contract balance did not decrease by rewardAmount.
        // We cannot know which party is allowed, so allow either beneficiary.

        bool targetIncreased = (afterReward_target == beforeReward_target + rewardAmount);
        bool meIncreased = (afterReward_me == beforeReward_me + rewardAmount);
        bool contractDecreasedByReward = (before_bal_contract == after_bal_contract + rewardAmount);

        // If rewardAmount is zero then increases by zero are indistinguishable; treat rewardAmount==0 as no-change requirement
        if (rewardAmount == 0) {
            assert((afterReward_target == beforeReward_target) && (afterReward_me == beforeReward_me) && (after_bal_contract == before_bal_contract));
        } else {
            // General implication
            if (txSucceeded && meetsMin && contractHadReward) {
                assert((targetIncreased || meIncreased) && contractDecreasedByReward);
            } else {
                assert((afterReward_target == beforeReward_target) && (afterReward_me == beforeReward_me) && (after_bal_contract == before_bal_contract));
            }
        }
    }

    receive() external payable {}
}

