contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry property test
    function run(address sender, address recipient, uint256 tAmount) public payable {
        require(sender != address(0) && recipient != address(0), "non-zero addrs");
        // We need to exercise flows where either sender or recipient is an allowed role.
        // The contract exposes no setter for _allowedRoles, but in constructor c's deployer (this test) was msg.sender when c was created
        // However the problem statement ensures c is freshly deployed and this contract was the deployer. Owner is msg.sender then.
        // There's no public to set allowedRoles. To reach role branches we rely on the fact that only the owner (this contract) had initial large balance via _mint.
        // The owner at deployment was msg.sender (the deployer of C). The checker deploys c and then deploys this test with c passed in; msg.sender for C's constructor was the original deployer (not this contract), so _allowedRoles likely false for all. To make the property general and safe, we assert invariants that hold regardless of whether special-role branches executed.

        // Read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 txRewardSenderBefore = c.txReward(sender);
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        // Attempt transfer, capture whether it reverts
        bool reverted;
        try c.transferFrom(sender, recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 txRewardSenderAfter = c.txReward(sender);
        uint256 txRewardRecipientAfter = c.txReward(recipient);

        // General rule asserted:
        // - totalSupply never changes
        // - if call reverted then balances and txReward unchanged (no partial effects)
        // - if call succeeded then sum of balances is conserved modulo that transfers may move tokens from or to address(this) as contract rewards; but totalSupply still unchanged
        // We express a conservative, provable invariant: totalSupply unchanged, and if reverted then all observed balances and txReward unchanged.
        assert(afterTotal == beforeTotal && (reverted ? (
            balSenderAfter == balSenderBefore && balRecipientAfter == balRecipientBefore && txRewardSenderAfter == txRewardSenderBefore && txRewardRecipientAfter == txRewardRecipientBefore
        ) : true));
    }

    receive() external payable {}
}

