    function run(address sender, address recipient, uint256 tAmount) public payable {
        require(sender != address(0) && recipient != address(0) && sender != recipient, true);

        // Prepare: ensure this contract is owner so it can call changeOwner if needed
        // Note: c was deployed by the checker with this test as deployer; owner is set in constructor of C
        // We will not call any owner-only functions to avoid changing allowed roles, instead rely on public surface.

        // Read balances and txReward before
        uint256 beforeSenderBal = c.balanceOf(sender);
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeRecipientTxReward = c.txReward(recipient);

        // We need both sender or recipient to be allowed roles for transfer to proceed in C's _transfer
        // The contract exposes no setter for _allowedRoles; but constructor set some roles? To make the property general,
        // we will attempt transferFrom pattern: first try to approve this test contract to move funds from sender
        // Then call c.transferFrom(sender, recipient, tAmount) and catch whether it reverts.

        bool reverted;
        try c.transferFrom(sender, recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterSenderBal = c.balanceOf(sender);
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterRecipientTxReward = c.txReward(recipient);

        // If the call reverted, then nothing changed in observable balances/txReward (since state didn't change)
        // If it didn't revert, then the sender's balance must be <= before, recipient's >= before.
        // Additionally, the increase in recipient's balance minus decrease in sender's balance must be >= 0
        // and equal to tAmount plus any reward credited to recipient during the transfer (captured by txReward delta).

        if (reverted) {
            assert(afterSenderBal == beforeSenderBal && afterRecipientBal == beforeRecipientBal && afterRecipientTxReward == beforeRecipientTxReward);
        } else {
            // general property for successful transfer: sender decreased by at least tAmount (in reflection terms may differ, but visible token balances should reflect net effect)
            // We assert non-strict relations and relation tying reward delta to txReward and recipient balance delta.
            uint256 senderDelta;
            if (beforeSenderBal >= afterSenderBal) { senderDelta = beforeSenderBal - afterSenderBal; } else { senderDelta = 0; }

            uint256 recipientDelta;
            if (afterRecipientBal >= beforeRecipientBal) { recipientDelta = afterRecipientBal - beforeRecipientBal; } else { recipientDelta = 0; }

            uint256 txRewardDelta;
            if (afterRecipientTxReward >= beforeRecipientTxReward) { txRewardDelta = afterRecipientTxReward - beforeRecipientTxReward; } else { txRewardDelta = 0; }

            // The recipientDelta is at least the visible transfer tAmount (if no fee mechanics) but in this contract rewards may add extra tokens from contract address.
            // We assert that recipientDelta >= txRewardDelta (reward contributes to recipient increase) and senderDelta >= tAmount - txRewardDelta (sender lost at least the transfer minus reward refunded)
            // Combine into a single assert expressing consistency: recipient increase equals sender decrease plus minted-from-contract (txRewardDelta) or at least not contradictory.

            assert(recipientDelta >= txRewardDelta && senderDelta + txRewardDelta >= tAmount);
        }
    }

    receive() external payable {}
}

