contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take these parameters: sender (the role-authorized address), recipient, and amount to transfer.
    // The test contract is the msg.sender for calls to c, so we must use c's public functions to set roles
    // however _allowedRoles is private; we can only interact by using transfer paths: the constructor of c
    // sets owner to deployer (the test deployer), but here InvMutTest is deployed after c. We therefore rely
    // on the fact that transfers will revert unless one of sender or recipient has an allowed role. The only
    // way to have an allowed role from outside is unknown, so instead we exercise the public transferFrom/approve
    // path: we will call transfer which will revert unless allowed role, so we instead attempt a transfer and
    // observe revert. We'll write a property about behavior when transfer succeeds: when transfer returns (no revert),
    // recipient's balance increased by amount and if amount >= minTxnAmount and contract had enough tokens,
    // txReward increases by rewardAmount; otherwise txReward unchanged.

    // Because we cannot set _allowedRoles, this test will try transfers and capture revert flag. The property
    // asserts the logical implication that when the transfer does NOT revert, the observed invariants hold.

    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0), true);

        // Read pre-state
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeContractBal = c.balanceOf(address(c));
        uint256 beforeTxReward = c.txReward(recipient);
        uint256 minTxn = c.minTxnAmount();
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        bool reverted = false;
        // Perform transfer as if from sender by using transferFrom: but this contract must have allowance.
        // Approve sender to spend from this contract is not helpful. Instead we attempt c.transfer(recipient, amount)
        // from this contract (msg.sender == address(this)). That will act as sender = address(this).
        // So use sender parameter only as input to the property (we cannot change msg.sender), but property will
        // concern any successful transfer from address(this).

        // Attempt the transfer; capture revert
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterContractBal = c.balanceOf(address(c));
        uint256 afterTxReward = c.txReward(recipient);

        // Compute expected reward amount when applicable, using safe arithmetic in uint256 domain
        uint256 expectedReward = 0;
        if (amount >= minTxn) {
            expectedReward = amount * rewardRate / percent;
        }

        // General rule: if the transfer succeeded (did not revert), then recipient's balance increased by at least amount,
        // and either (if amount >= minTxn and contract had enough balance before) txReward increased by expectedReward,
        // otherwise txReward did not increase. If transfer reverted, no further guarantees (we simply allow any state).
        assert(reverted || (
            // recipient balance increase at least amount
            afterRecipientBal >= beforeRecipientBal + amount
            && (
                // if eligible for reward and contract had enough tokens before
                (amount >= minTxn && beforeContractBal >= expectedReward && afterTxReward >= beforeTxReward + expectedReward)
                ||
                // otherwise txReward did not increase
                ( (amount < minTxn) || (beforeContractBal < expectedReward) ) && afterTxReward == beforeTxReward
            )
        ));
    }

    receive() external payable {}
}

