    // We take parameters: sender and recipient are addresses to act as participants,
    // amount is transfer amount, and allowedFlag decides whether to mark sender or recipient allowed.
    // We cannot directly set _allowedRoles (it's private), but we can simulate allowed role by
    // using functions that make caller the owner (constructor of c set owner to deployer of c)
    // and calling changeOwner is onlyOwner; however we cannot change c's internal allowed roles.
    // Instead, we rely on the public behavior: transfers will revert unless one of parties has an allowed role.
    // So the property we can assert is: after any successful transfer attempt, totalSupply remains constant
    // and sum of balances of sender+recipient+address(this) (observed) changes by at most 0 (i.e., conserved across those addresses)
    // We'll perform transfer from msg.sender (this contract) to recipient using c.transfer and also attempt transferFrom
    // to exercise both paths. To ensure the transfer can succeed, we will transfer zero or small amounts that respect balances.

    // Single public test function per constraints
    function run(address recipient, uint256 amount, bool useTransferFrom) public payable {
        require(recipient != address(0));

        // Observe totalSupply before
        uint256 tBefore = c.totalSupply();

        // Observe balances before
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 balRecBefore = c.balanceOf(recipient);

        bool reverted = false;

        // If using transferFrom, first approve this contract as spender from this address's tokens
        if (useTransferFrom) {
            // approve is external and will set allowance for msg.sender (which is this test contract) to spend from address(this)
            // But transferFrom requires allowance from the token holder; since msg.sender is this contract and holder is this contract,
            // we can approve and then transferFrom using the same contract as caller (this contract). That will attempt to move tokens from address(this) to recipient.
            c.approve(address(this), amount);
            try c.transferFrom(address(this), recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.transfer(recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after
        uint256 tAfter = c.totalSupply();
        uint256 balThisAfter = c.balanceOf(address(this));
        uint256 balRecAfter = c.balanceOf(recipient);

        // General rule asserted: totalSupply is unchanged by transfers, and if the call succeeded (not reverted) then
        // the sum of observed balances of the two involved accounts changed exactly by the transfer amount in the sender->recipient direction.
        // That is: if not reverted, balThisBefore - balThisAfter == amount and balRecAfter - balRecBefore == amount (for transfer from this contract)
        // Because under reflection mechanics and possible rewards, the contract may mint internal reflection amounts, but totalSupply should remain same.
        // To avoid underflow in assert, compute differences with addition form.

        if (!reverted) {
            // assert totalSupply unchanged and net change equals zero-sum: (balThisBefore + balRecBefore) == (balThisAfter + balRecAfter)
            assert(tBefore == tAfter && (balThisBefore + balRecBefore) == (balThisAfter + balRecAfter));
        } else {
            // If reverted, still totalSupply must be unchanged
            assert(tBefore == tAfter);
        }
    }

