contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test transfers between two addresses (a and b), and whether when transfer succeeds
    // the totalSupply remains unchanged and the recorded txReward corresponds to any reward
    // emission to sender/recipient when transfer meets minTxnAmount. We cannot access internal
    // totals, so we observe: totalSupply(), balanceOf(a), balanceOf(b), balanceOf(address(this) as proxy contract?),
    // but we must interact via c only. We'll use the InvMutTest contract's address as one participant
    // and an arbitrary third address through approve/transferFrom pattern is not available, so we use
    // c.transfer from this contract after setting allowances by calling c.approve (msg.sender = this). 

    // Single public test function
    function run(address a, address b, uint256 amount, bool makeSenderAllowed, bool makeRecipientAllowed) public payable {
        require(a != address(0) && b != address(0));
        // Pre: ensure this contract is owner to call owner-only functions if needed. The deployed C sets owner to deployer (the checker), not us.
        // We cannot call changeOwner. But we can observe and interact: our calls from this contract must obey _allowedRoles checks inside C's _transfer.
        // To make roles allowed, we cannot mutate C's private mapping; so we instead perform transfers where either sender or recipient is this test contract (which was the deployer of C per instructions), so it may be owner and likely allowed? To be conservative, we will call transfer between this contract and b using this contract as sender so that _allowedRoles[sender] or recipient gating may behave; we cannot set roles, so the property will consider both possibilities by checking if transfer reverts.

        // Read before values
        uint256 totalBefore = c.totalSupply();
        uint256 balA_before = c.balanceOf(a);
        uint256 balB_before = c.balanceOf(b);
        uint256 balThis_before = c.balanceOf(address(this));
        uint256 txRewardA_before = c.txReward(a);
        uint256 txRewardB_before = c.txReward(b);
        uint256 minTxn = c.minTxnAmount();
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        // Try transfer: from this contract to b. We need this contract to hold enough tokens; initial mint may have given deployer (checker) tokens, not us.
        // To ensure we have tokens to attempt a transfer, we'll attempt a transfer of 0 which should revert due to tAmount>0 requirement, so instead we try/catch and record revert.
        bool reverted;
        try c.transfer(b, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 totalAfter = c.totalSupply();
        uint256 balA_after = c.balanceOf(a);
        uint256 balB_after = c.balanceOf(b);
        uint256 balThis_after = c.balanceOf(address(this));
        uint256 txRewardA_after = c.txReward(a);
        uint256 txRewardB_after = c.txReward(b);

        // General rule asserted:
        // - totalSupply never changes
        // - if transfer reverted then all balances and txRewards unchanged
        // - if transfer succeeded then totalSupply unchanged and sum of observed balances changes equals zero
        //   (i.e., tokens conserved among observed accounts: this,a,b,contract) but we only observe this,a,b and contract is c itself via its internal balance which is accessible via balanceOf(address(c)). Use that too.
        uint256 balC_before = c.balanceOf(address(c));
        uint256 balC_after = c.balanceOf(address(c));

        if (reverted) {
            assert(totalAfter == totalBefore && balA_after == balA_before && balB_after == balB_before && balThis_after == balThis_before && txRewardA_after == txRewardA_before && txRewardB_after == txRewardB_before && balC_after == balC_before);
        } else {
            // transfer succeeded: total supply preserved
            // conservation: sum of balances of this,a,b,contract unchanged
            uint256 sumBefore = balThis_before + balA_before + balB_before + balC_before;
            uint256 sumAfter = balThis_after + balA_after + balB_after + balC_after;
            assert(totalAfter == totalBefore && sumAfter == sumBefore);
        }
    }

    receive() external payable { }
}

