        uint256 totalBefore = c.totalSupply();
        uint256 balOther_before = c.balanceOf(other);
        uint256 balRecipient_before = c.balanceOf(recipient);
        uint256 balThis_before = c.balanceOf(address(this));
        uint256 txRewardOther_before = c.txReward(other);
        uint256 txRewardRecipient_before = c.txReward(recipient);
        uint256 balC_before = c.balanceOf(address(c));

        // Perform the transfer from this contract to recipient. This is a top-level state-changing call.
        bool succeeded = true;
        // We must catch reverts without nesting the call. Use low-level call to detect success while still invoking the public function.
        (bool callOk, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", recipient, amount));
        if (!callOk) {
