contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt a normal transfer and check balances/update
    function run(address sender, address recipient, uint256 tAmount) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero addrs");
        require(sender != recipient, "distinct");

        // We interact with the freshly deployed c where this contract is the deployer (owner).
        // Ensure the test exercises the plain transfer branch (neither sender nor recipient has allowed role).
        // The contract exposes no setter for _allowedRoles; by default both should be false, so we proceed.

        // We can only act as msg.sender == address(this) when calling c, so to simulate a transfer from
        // `sender` we use c.transferFrom with this contract as caller; but transferFrom requires allowance from sender.
        // To observe the basic non-role transfer behavior we instead perform the following sequence:
        // 1) Use the owner (this contract is the deployer of c) balance to transfer tokens to `sender`.
        //    The constructor of c minted all tokens to msg.sender at deployment; here msg.sender for that
        //    deployment was this InvMutTest when test harness deploys c. So this contract holds tokens.
        // 2) From this contract call c.transfer(sender, amount) to fund sender.
        // 3) Then call c.transferFrom(sender, recipient, tAmount) after sender has approved this contract.

        // Step 1: decide funding amount. To allow the asserted property to be meaningful, require funding >= tAmount.
        uint256 fundAmount = tAmount;

        // fund sender: this contract (current caller) has initial minted rOwned so it can transfer
        // Note: transfer is called on c as this contract (msg.sender == address(this))
        bool fundReverted;
        try c.transfer(sender, fundAmount) {
            fundReverted = false;
        } catch {
            fundReverted = true;
        }

        // If funding reverted, we cannot proceed; assert later will capture that transfer did revert when expected.

        // Now have sender approve this contract to spend tAmount.
        // To call approve as sender we cannot impersonate sender. But c.approve is external and uses msg.sender.
        // We cannot make sender call approve. Instead, use a different approach:
        // Use c.transfer to move tokens directly from sender to recipient by making the contract itself perform
        // the transfer: since transfer uses msg.sender as sender, we can make this contract be the actual sender.
        // Therefore to test the no-role direct transfer branch we perform a transfer from this contract to recipient
        // and assert balances change accordingly. That exercises the branch where neither sender nor recipient has allowed role.

        // Read balances before
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(recipient);

        bool txReverted;
        try c.transfer(recipient, tAmount) {
            txReverted = false;
        } catch {
            txReverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(recipient);

        // General rule asserted:
        // If the transfer did not revert then sender (here address(this)) balance decreased by exactly tAmount
        // and recipient balance increased by exactly tAmount. If it reverted then balances must be unchanged.
        assert(
            // successful call: exact balance movements
            (!txReverted && balSenderBefore >= tAmount &&
                balSenderAfter + tAmount == balSenderBefore &&
                balRecipientAfter == balRecipientBefore + tAmount)
            ||
            // reverted call: balances unchanged
            (txReverted && balSenderAfter == balSenderBefore && balRecipientAfter == balRecipientBefore)
        );
    }

    receive() external payable {}
}
